// SCIO monthly/weekly source refresh window. Inclusive calendar dates in Europe/Vienna.
// For historical backfill, edit the "02 - backfill inputs" node. This fetches transactions by date;
// it must never infer old pipeline stages from the current Salesforce Opportunity state.
const p=$input.first().json;
const pad=n=>String(n).padStart(2,'0');
const fmt=d=>`${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())}`;
const utc=(y,m,d)=>new Date(Date.UTC(y,m,d));
const today=new Date(); const d=utc(today.getUTCFullYear(),today.getUTCMonth(),today.getUTCDate());
let from,to;
if (p.mode==='weekly') { const start=new Date(d); start.setUTCDate(start.getUTCDate()-90); from=fmt(start); to=fmt(d); }
else if (p.mode==='monthly') { const monthStart=utc(d.getUTCFullYear(),d.getUTCMonth(),1);const threeBack=utc(monthStart.getUTCFullYear(),monthStart.getUTCMonth()-3,1);const through=new Date(monthStart);through.setUTCDate(through.getUTCDate()-1);from=fmt(threeBack);to=fmt(through); }
else { from=p.backfill_from;to=p.backfill_through; }
if(!/^\d{4}-\d{2}-\d{2}$/.test(from)||!/^\d{4}-\d{2}-\d{2}$/.test(to)||from>to)throw Error('Invalid from/through dates');
return [{json:{mode:p.mode,date_from:from,date_to:to,run_id:`SCIO_${p.mode}_${Date.now()}`,run_at:new Date().toISOString()}}];

const run=$('03 - Build run window').first().json;
const rules=$('04Q - Read fee rules').all().map(x=>x.json);
const allowed=new Set(rules.filter(x=>String(x.classification).toUpperCase()==='FEE'&&String(x.include_as_fee).toUpperCase()==='Y'&&x.approved_by).map(x=>String(x.qbo_item_id)));
function serial(d){return Math.round((Date.parse(d+'T00:00:00Z')-Date.UTC(1899,11,30))/86400000);}
const now=new Date().toISOString();const out=[];
for(const item of $input.all()){
 const inv=item.json; if(!inv.Id||!inv.TxnDate)continue;
 const currency=inv.CurrencyRef?.value||'EUR';
 for(const ln of inv.Line||[]){
  if(ln.DetailType!=='SalesItemLineDetail')continue;
  const id=String(ln.Id??ln.LineNum??'no-line-id');
  const itemId=String(ln.SalesItemLineDetail?.ItemRef?.value??'');
  const amt=Number(ln.Amount??0);
  const status=currency!=='EUR'?'FX_REVIEW':allowed.has(itemId)?'APPROVED_FEE':'UNCLASSIFIED';
  const record={record_key:`QBO|Invoice|${inv.Id}|${id}`,object_type:'Invoice',source_id:String(inv.Id),source_line_id:id,
    txn_date_iso:inv.TxnDate,txn_date_serial:serial(inv.TxnDate),qbo_customer_id:String(inv.CustomerRef?.value||''),
    sales_line_amount_eur:currency==='EUR'?amt:'',approved_fee_amount_eur:status==='APPROVED_FEE'?amt:'',
    classification:status,qbo_item_id:itemId,currency,modified_at:inv.MetaData?.LastUpdatedTime||'',sync_at:now,run_id:run.run_id,
    note:status==='APPROVED_FEE'?'Approved item mapping; still excludes credit notes until added':'Requires item and FX mapping; NOT revenue'};
  out.push({json:record});
 }
}
return out;

const run = $('03 - Build run window').first().json;
const now = new Date().toISOString();
const output = [];

function dateSerial(value) {
  const date = String(value ?? '').slice(0, 10);

  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return '';

  const timestamp = Date.parse(date + 'T00:00:00Z');
  if (!Number.isFinite(timestamp)) return '';

  return Math.round(
    (timestamp - Date.UTC(1899, 11, 30)) / 86400000
  );
}

function numericOrBlank(value, field, id) {
  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  ) {
    return '';
  }

  const number = Number(value);

  if (!Number.isFinite(number)) {
    throw new Error(
      `Invalid ${field} for opportunity ${id}: ${value}`
    );
  }

  return number;
}

function multiSelect(value) {
  return (
    Array.isArray(value)
      ? value
      : String(value ?? '').split(';')
  )
    .map(v => String(v).trim())
    .filter(Boolean)
    .join(';');
}

for (const item of $input.all()) {
  const o = item.json;

  if (!o.Id) continue;

  if (
    typeof o.IsClosed !== 'boolean' ||
    typeof o.IsWon !== 'boolean'
  ) {
    throw new Error(
      `Missing IsClosed/IsWon for ${o.Id}`
    );
  }

  if (o.IsWon && !o.IsClosed) {
    throw new Error(
      `Inconsistent Won/Closed for ${o.Id}`
    );
  }

  const currency =
    String(o.CurrencyIsoCode ?? '').trim() || 'UNKNOWN';

  // Preserve original Salesforce amounts in their
  // own currency without applying an FX assumption.
  const sourceAmount = numericOrBlank(
    o.Amount, 'Amount', o.Id
  );

  const sourceProfit = numericOrBlank(
    o.Expected_Profit__c, 'Expected Profit', o.Id
  );

  const profitabilityRatio = numericOrBlank(
    o.ProfitabilityRatio__c,
    'Profitability Ratio',
    o.Id
  );

  const probability = numericOrBlank(
    o.Probability, 'Probability', o.Id
  );

  const decisionDate = String(
    o.Decision_Date__c || o.CloseDate || ''
  ).slice(0, 10);

  output.push({
    json: {
      record_key: `SF|Opportunity|${o.Id}`,
      opportunity_id: String(o.Id),
      account_id: String(o.AccountId || ''),
      account_name: String(
        o.Account?.Name || o['Account.Name'] || ''
      ),
      created_at: String(o.CreatedDate || ''),
      name: String(o.Name || ''),

      // EUR-only columns
      amount_eur:
        currency === 'EUR' ? sourceAmount : '',

      currency: currency,
      stage: String(o.StageName || ''),
      is_closed: o.IsClosed ? 'Y' : 'N',
      is_won: o.IsWon ? 'Y' : 'N',

      closed_at: String(o.CloseDate || ''),
      decision_date_iso: decisionDate,
      decision_date_serial: dateSerial(decisionDate),

      proposal_submitted:
        typeof o.Proposal_Submitted__c === 'boolean'
          ? (o.Proposal_Submitted__c ? 'Y' : 'N')
          : 'REVIEW',

      qualified:
        typeof o.Qualified__c === 'boolean'
          ? (o.Qualified__c ? 'Y' : 'N')
          : 'REVIEW',

      owner_name: String(
        o.Owner?.Name || o['Owner.Name'] || ''
      ),
      owner_id: String(o.OwnerId || ''),
      last_modified: String(o.LastModifiedDate || ''),
      sync_at: now,
      run_id: run.run_id,

      decision_date_basis: o.Decision_Date__c
        ? 'ACTUAL_DECISION_DATE'
        : 'CLOSEDATE_PROXY_REVIEW',

      sector_raw: multiSelect(o.Sector__c),

      expected_profit_eur:
        currency === 'EUR' ? sourceProfit : '',

      profitability_ratio_raw: profitabilityRatio,

      project_id: String(
        o.Project_New_Id__c ?? ''
      ).trim(),

      probability_pct: probability,
      opportunity_type: String(o.Type ?? '').trim(),

      // New fields: source-currency values
      amount_source_currency: sourceAmount,
      expected_profit_source_currency: sourceProfit
    }
  });
}

if (!output.length) {
  throw new Error('No Salesforce opportunities received.');
}

const keys = output.map(x => x.json.record_key);

if (new Set(keys).size !== keys.length) {
  throw new Error('Duplicate opportunity keys found.');
}

const records = output.map(x => x.json);

console.log('Salesforce reporting extraction:', {
  total: records.length,
  currencies: records.reduce((acc, r) => {
    acc[r.currency] = (acc[r.currency] || 0) + 1;
    return acc;
  }, {}),
  withSourceAmount: records.filter(
    r => r.amount_source_currency !== ''
  ).length,
  withSourceProfit: records.filter(
    r => r.expected_profit_source_currency !== ''
  ).length,
  withVertical: records.filter(
    r => r.sector_raw !== ''
  ).length
});

return output;

const run = $('03 - Build run window').first().json;
const rows = $input.all().map(item => item.json);

const now = new Date().toISOString();
const output = [];
const keys = new Set();

const stats = {
  total: rows.length,
  accepted: 0,
  blank: 0,
  unapproved: 0,
  unverifiedZero: 0,
  invalid: 0
};

function validDate(value) {
  const text = String(value ?? '').trim().slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) return false;
  const date = new Date(text + 'T00:00:00Z');
  return !Number.isNaN(date.getTime()) &&
    date.toISOString().slice(0, 10) === text;
}

for (const row of rows) {
  const approval = String(
    row.approval_status ?? ''
  ).trim().toLowerCase();

  if (approval !== 'approved') {
    stats.unapproved++;
    continue;
  }

  const metricId = String(row.metric_id ?? '').trim();
  const grain = String(row.grain ?? '').trim().toUpperCase();
  const periodStart = String(row.period_start ?? '').trim();
  const periodEnd = String(row.period_end ?? '').trim();
  const approvedBy = String(row.approved_by ?? '').trim();
  const evidence = String(row.evidence_link ?? '').trim();
  const scope = String(row.scope ?? 'ALL').trim() || 'ALL';

  if (
    !metricId ||
    !['M', 'W'].includes(grain) ||
    !validDate(periodStart) ||
    (periodEnd && !validDate(periodEnd)) ||
    (periodEnd && periodEnd <= periodStart) ||
    !approvedBy
  ) {
    stats.invalid++;
    continue;
  }

  const raw = row.value_numeric;

  if (
    raw === null ||
    raw === undefined ||
    String(raw).trim() === ''
  ) {
    stats.blank++;
    continue;
  }

  const rawText = String(raw).trim();

  if (
    !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(rawText)
  ) {
    stats.invalid++;
    continue;
  }

  const value = Number(rawText);

  if (!Number.isFinite(value)) {
    stats.invalid++;
    continue;
  }

  // A zero without evidence must not be
  // interpreted as a verified measurement.
  if (value === 0 && !evidence) {
    stats.unverifiedZero++;
    continue;
  }

  const metricKey =
    `${metricId}|${grain}|${periodStart}|${scope}`;

  if (keys.has(metricKey)) {
    throw new Error(
      `Duplicate GW input metric key: ${metricKey}`
    );
  }

  keys.add(metricKey);

  // No evidence means provisional, even when
  // the source row says "Approved".
  const status = evidence
    ? 'APPROVED MANUAL'
    : 'PROVISIONAL - REVIEW';

  output.push({
    json: {
      metric_key: metricKey,
      metric_id: metricId,
      grain: grain,
      period_start: periodStart,
      period_end: periodEnd,
      value_numeric: value,
      unit: String(row.unit ?? ''),
      status: status,
      source: 'Google Workspace manual tracker',
      updated_at: String(row.updated_at || now),
      approved_by: approvedBy,
      evidence_link: evidence,
      run_id: run.run_id,
      notes: String(row.notes ?? '') +
        (evidence
          ? ''
          : ' | Evidence missing; provisional only.'),
      data_as_of: String(row.updated_at || '')
    }
  });

  stats.accepted++;
}

console.log('GW validation summary:', stats);

return output;

// Scio Network - 07Q - Normalize PNL
// Full replacement, November 2026. Input: 06Q - Extract PNL XLSX.
// Output: one reconciled P&L record per completed month.
// Keeps the fields used by 08Q - Prepare PNL Metrics unchanged.

const rows = $input.all().map(item => item.json.row);

if (!rows.length || !rows.every(Array.isArray)) {
  throw new Error('No valid QuickBooks Excel rows received.');
}

const monthNumbers = {
  Jan: 1, Feb: 2, Mar: 3, Apr: 4,
  May: 5, Jun: 6, Jul: 7, Aug: 8,
  Sep: 9, Oct: 10, Nov: 11, Dec: 12,
};

const round2 = value =>
  Math.round((value + Number.EPSILON) * 100) / 100;

const now = new Date();
const syncAt = now.toISOString();
const currentMonth = syncAt.slice(0, 7);

function nextMonth(period) {
  const [year, month] = period.split('-').map(Number);
  return new Date(Date.UTC(year, month, 1))
    .toISOString().slice(0, 10);
}

// Locate the exact month headers; ignore the Total column and partial
// ranges such as 'Nov 1-3 2026'. Exclude the current unfinished month.
const header = rows.find(row =>
  row.some(value =>
    /^(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) 20\d{2}$/
      .test(String(value).trim())
  )
);

if (!header) {
  throw new Error('QuickBooks month header not found.');
}

const months = [];

header.forEach((value, column) => {
  const match = String(value).trim().match(
    /^(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) (20\d{2})$/
  );

  if (!match) return;

  const year = Number(match[2]);
  const month = monthNumbers[match[1]];
  const period = `${year}-${String(month).padStart(2, '0')}`;

  if (period >= currentMonth) return;

  months.push({ column, period, year });
});

months.sort((a, b) => a.period.localeCompare(b.period));

if (!months.length) {
  throw new Error('No completed monthly columns found.');
}

function findRow(label) {
  const matches = rows.filter(
    row => String(row[0] ?? '').trim() === label
  );

  if (matches.length !== 1) {
    throw new Error(
      `Expected exactly one P&L line '${label}', ` +
      `found ${matches.length}.`
    );
  }

  return matches[0];
}

function amount(row, col, label) {
  const raw = row[col];

  if (
    raw === null ||
    raw === undefined ||
    String(raw).trim() === ''
  ) {
    return 0;
  }

  const value = Number(raw);

  if (!Number.isFinite(value)) {
    throw new Error(
      `Invalid amount in '${label}', column ${col}: ${raw}`
    );
  }

  return round2(value);
}

const accountLabels = {
  fee_revenue: '31000 Project Honorarium',

  reimbursable_income:
    'Total for 39000 Other operating income',

  total_income: 'Total Income',

  subcontractor_fees:
    '41100 Honorarium_Sub-contractors',

  partner_fees:
    '41200 Honorarium_Partners',

  project_backstopping:
    '41300 Project Backstopping',

  expert_costs:
    'Total for 41000 Expert Costs',

  other_project_costs:
    'Total for 42000 Other Project Costs',

  cost_of_sales: 'Total Cost of Sales',

  gross_profit: 'Gross Profit',

  salaries_operating:
    '61100 Salaries',

  social_security_operating:
    '61300 Social Security Contributions',

  professional_fees_internal_operating:
    '62100 Professional Services Fees - Internal',

  operating_expenses:
    'Total Expenses',

  other_expenses:
    'Total Other Expenses',

  net_earnings:
    'Net Earnings'
};

const sourceRows = Object.fromEntries(
  Object.entries(accountLabels).map(
    ([key, label]) => [key, findRow(label)]
  )
);

function reconcile(period, name, reported, calculated) {
  if (Math.abs(reported - calculated) > 0.03) {
    throw new Error(
      `${period}: ${name} does not reconcile. ` +
      `QuickBooks=${reported}; calculated=${calculated}`
    );
  }
}

const ytdByYear = {};
const output = [];

for (const entry of months) {
  const p = {};

  for (const [key, row] of Object.entries(sourceRows)) {
    p[key] = amount(
      row,
      entry.column,
      accountLabels[key]
    );
  }

  // Check the QuickBooks totals.

  reconcile(
    entry.period,
    'Total income',
    p.total_income,
    round2(p.fee_revenue + p.reimbursable_income)
  );

  reconcile(
    entry.period,
    'Expert-cost subtotal',
    p.expert_costs,
    round2(
      p.subcontractor_fees +
      p.partner_fees +
      p.project_backstopping
    )
  );

  reconcile(
    entry.period,
    'Cost of sales',
    p.cost_of_sales,
    round2(p.expert_costs + p.other_project_costs)
  );

  reconcile(
    entry.period,
    'Gross profit',
    p.gross_profit,
    round2(p.total_income - p.cost_of_sales)
  );

  reconcile(
    entry.period,
    'Net earnings',
    p.net_earnings,
    round2(
      p.gross_profit -
      p.operating_expenses -
      p.other_expenses
    )
  );

  // Calculate YTD fee revenue.

  const ytd = ytdByYear[entry.year] ?? 0;

  ytdByYear[entry.year] = round2(
    ytd + p.fee_revenue
  );

  // Flag figures that may require Finance review.

  const flags = [];

  if (p.total_income < 0) {
    flags.push('NEGATIVE_INCOME');
  }

  if (
    p.total_income > 0 &&
    p.cost_of_sales === 0
  ) {
    flags.push('ZERO_COST_OF_SALES');
  }

  if (
    p.total_income > 0 &&
    p.gross_profit / p.total_income > 0.9
  ) {
    flags.push('GROSS_MARGIN_OVER_90_PCT');
  }

  if (
    p.total_income !== 0 &&
    p.gross_profit / p.total_income < 0
  ) {
    flags.push('NEGATIVE_GROSS_MARGIN');
  }

  // Preserve existing property names for downstream 08Q metrics.

  output.push({
    json: {
      record_key: `QBO|PNL|${entry.period}`,

      period: entry.period,
      period_start: `${entry.period}-01`,
      period_end: nextMonth(entry.period),

      currency: 'EUR',
      accounting_basis: 'ACCRUAL',

      // Revenue
      fee_revenue: p.fee_revenue,
      fee_revenue_ytd: ytdByYear[entry.year],
      reimbursable_income: p.reimbursable_income,
      total_income: p.total_income,

      // Direct costs
      subcontractor_fees: p.subcontractor_fees,
      partner_fees: p.partner_fees,
      project_backstopping: p.project_backstopping,
      expert_costs: p.expert_costs,
      other_project_costs: p.other_project_costs,
      cost_of_sales: p.cost_of_sales,

      // Gross profitability
      gross_profit: p.gross_profit,

      gross_margin_ratio:
        p.total_income === 0
          ? ''
          : p.gross_profit / p.total_income,

      // Personnel and operating expenses
      salaries_operating: p.salaries_operating,
      social_security_operating:
        p.social_security_operating,

      professional_fees_internal_operating:
        p.professional_fees_internal_operating,

      operating_expenses: p.operating_expenses,

      operating_result_before_other_expenses:
        round2(
          p.gross_profit - p.operating_expenses
        ),

      // Net profitability
      other_expenses: p.other_expenses,
      net_earnings: p.net_earnings,

      net_margin_ratio:
        p.total_income === 0
          ? ''
          : p.net_earnings / p.total_income,

      // Metadata
      review_flags: flags.join(';'),
      source: 'QBO_PNL_MONTH',
      source_file: 'QBO_PNL_MONTH_LATEST.xlsx',
      status: 'PROVISIONAL - REVIEW',
      sync_at: syncAt
    }
  });
}

// Check for duplicate periods.

if (
  new Set(output.map(o => o.json.record_key)).size !==
  output.length
) {
  throw new Error('Duplicate P&L month keys.');
}

// Log reconciliation results.

console.log('QBO monthly P&L reconciliation:', {
  months: output.length,

  periods: output
    .map(o => o.json.period)
    .join(', '),

  totalIncome: round2(
    output.reduce(
      (n, o) => n + o.json.total_income,
      0
    )
  ),

  grossProfit: round2(
    output.reduce(
      (n, o) => n + o.json.gross_profit,
      0
    )
  ),

  netEarnings: round2(
    output.reduce(
      (n, o) => n + o.json.net_earnings,
      0
    )
  ),

  reviewMonths: output
    .filter(o => o.json.review_flags !== '')
    .map(o => ({
      month: o.json.period,
      flags: o.json.review_flags
    }))
});

return output;

/**
 * SCIO NETWORK — 08Q Prepare PNL Metrics
 *
 * Input: 07Q - Normalize PNL
 * Output: monthly financial readings for METRIC_VALUES
 *
 * Expected for 22 months:
 * 7 monthly metrics x 22 = 154
 * 2026 revenue KR x 10 = 10
 * Total = 164 items
 */

const records = $input.all().map(item => item.json);

if (!records.length) {
  throw new Error("No QuickBooks P&L data received");
}

const now = new Date().toISOString();
const runId = `QBO-PNL-${now}`;
const output = [];
const seen = new Set();

const evidenceLink =
  "https://drive.google.com/file/d/" +
  "16XLD4gP4OhTBBSsKhuzM9A13KFzO0TrH/view";

function nextMonth(periodStart) {
  const [year, month] = periodStart
    .slice(0, 7)
    .split("-")
    .map(Number);

  return new Date(Date.UTC(year, month, 1))
    .toISOString()
    .slice(0, 10);
}

function addMetric(id, record, value, unit, note) {
  if (
    value === "" ||
    value === null ||
    value === undefined ||
    !Number.isFinite(Number(value))
  ) {
    throw new Error(
      `Invalid value for ${id}, ${record.period_start}`
    );
  }

  const metricKey =
    `${id}|M|${record.period_start}|ALL`;

  if (seen.has(metricKey)) {
    throw new Error(`Duplicate key: ${metricKey}`);
  }

  seen.add(metricKey);

  output.push({
    json: {
      metric_key: metricKey,
      metric_id: id,
      grain: "M",
      period_start: record.period_start,
      period_end: nextMonth(record.period_start),
      value_numeric: Number(value),
      unit: unit,
      status: "PROVISIONAL - REVIEW",
      source: "QuickBooks P&L by Month",
      updated_at: now,
      approved_by: "",
      evidence_link: evidenceLink,
      run_id: runId,
      notes: note,
      data_as_of: ""
    }
  });
}

records.sort((a, b) =>
  String(a.period_start).localeCompare(
    String(b.period_start)
  )
);

const seenPeriods = new Set();

for (const record of records) {
  const period = String(record.period_start || "");

  if (!/^\d{4}-(0[1-9]|1[0-2])-01$/.test(period)) {
    throw new Error(`Invalid reporting period: ${period}`);
  }

  if (seenPeriods.has(period)) {
    throw new Error(`Duplicate P&L month: ${period}`);
  }

  seenPeriods.add(period);

  const financialMetrics = [
    {
      id: "SUP-QB-REVENUE",
      value: record.fee_revenue,
      unit: "EUR",
      note: "Monthly recognized fee revenue, excluding reimbursable income."
    },
    {
      id: "SUP-QB-TOTAL-INCOME",
      value: record.total_income,
      unit: "EUR",
      note: "Total monthly accounting income."
    },
    {
      id: "SUP-QB-COST-OF-SALES",
      value: record.cost_of_sales,
      unit: "EUR",
      note: "Monthly accounting cost of sales."
    },
    {
      id: "SUP-QB-GROSS-PROFIT",
      value: record.gross_profit,
      unit: "EUR",
      note: "Total accounting income minus cost of sales."
    },
    {
      id: "SUP-QB-NET-EARNINGS",
      value: record.net_earnings,
      unit: "EUR",
      note: "Accounting net earnings after operating and other expenses."
    },
    {
      id: "SUP-QB-GROSS-MARGIN-PCT",
