// Parse the ECB's quoted CSV format.
function parseCsv(text) {
  if (typeof text !== 'string' || !text.trim()) {
    throw new Error('ECB response is empty or not text.');
  }

  const rows = [];
  let row = [];
  let cell = '';
  let quoted = false;

  for (let i = 0; i < text.length; i++) {
    const c = text[i];

    if (quoted) {
      if (c === '"' && text[i + 1] === '"') {
        cell += '"';
        i++;
      } else if (c === '"') {
        quoted = false;
      } else {
        cell += c;
      }
    } else if (c === '"') {
      quoted = true;
    } else if (c === ',') {
      row.push(cell);
      cell = '';
    } else if (c === '\n') {
      row.push(cell);
      if (row.some(v => v.trim() !== '')) {
        rows.push(row);
      }
      row = [];
      cell = '';
    } else if (c !== '\r') {
      cell += c;
    }
  }

  if (quoted) {
    throw new Error('Unclosed quote in ECB CSV.');
  }

  if (cell !== '' || row.length) {
    row.push(cell);
    rows.push(row);
  }

  if (rows.length < 2) {
    throw new Error('ECB CSV contains no observations.');
  }

  const headers = rows.shift().map(
    v => v.replace(/^\uFEFF/, '').trim()
  );

  const periodIndex = headers.indexOf('TIME_PERIOD');
  const currencyIndex = headers.indexOf('CURRENCY');
  const valueIndex = headers.indexOf('OBS_VALUE');

  if (
    periodIndex < 0 ||
    currencyIndex < 0 ||
    valueIndex < 0
  ) {
    throw new Error(
      `Missing ECB CSV columns: ${headers.join(', ')}`
    );
  }

  return rows
    .map(r => ({
      period: String(r[periodIndex] || '').trim(),
      currency: String(r[currencyIndex] || '').trim(),
      value: Number(r[valueIndex])
    }))
    .filter(r =>
      ['USD', 'GBP'].includes(r.currency) &&
      Number.isFinite(r.value) &&
      r.value > 0
    );
}

